<script setup>
import { computed,inject,ref,onBeforeUnmount } from 'vue';
import {useRoute} from 'vue-router';
import {agentReportKey} from '../../lib/cc-agent-report-context';
import {watchVisibleReport} from '../../lib/cc-visible-report';
import { ccCall } from '../../api/cc';
import CCDataTable from './CCDataTable.vue';
const route=useRoute(),context=inject(agentReportKey,null);
const selection=computed(()=>{const scope=context?.agentScope?.value;return scope?.mode==='single'&&scope.single?[scope.single]:scope?.mode==='multi'?scope.multiple:[];});
const batchSize=ref(15);
const emit=defineEmits(['open']);const days=ref(30),closed=ref(false),statuses=ref([]),owner=ref(''),data=ref(null),rows=ref([]),busy=ref(false),error=ref('');let generation=0,controller;
const columns=[{key:'lead_name',label:'Client'},{key:'name',label:'Lead'},{key:'ph4',label:'Phone',value:r=>'••••'+r.ph4},{key:'owner',label:'Agent'},{key:'sub',label:'Last outcome'},{key:'last',label:'Last call'},{key:'next',label:'Next follow-up'},{key:'branch',label:'Branch'}];
async function load(more=false){const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';if(!more){rows.value=[];data.value=null;}try{const result=await ccCall('life_cc_nofu_v1',{agents:JSON.stringify(selection.value),days:days.value,closed:+closed.value,statuses:JSON.stringify(statuses.value),owner:owner.value,start:more?rows.value.length:0,limit:more?batchSize.value:15},controller.signal);if(token!==generation)return;data.value=result;rows.value=more?[...rows.value,...result.rows]:result.rows;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
const visible=()=>Boolean(route.meta.standaloneAgent360||route.meta.agentSubtab==='nofollowup');
watchVisibleReport(()=>[selection.value.join('|')],visible,()=>load(),()=>!!data.value&&!error.value);onBeforeUnmount(()=>{generation++;controller?.abort();});
</script>
<template><section class="cc-card cc-nofu-card"><header><div><h2>No follow-up since N days</h2><p>Find leads that need an agent call-back. Client phone numbers stay masked.</p></div></header><form class="cc-filters" @submit.prevent="load()"><label>Days since last call<input v-model.number="days" type="number" min="1" max="7300" required></label><label class="cc-check"><input v-model="closed" type="checkbox"> Include closed leads</label><label>Agent<select v-model="owner"><option value="">All permitted agents</option><option v-for="a in data?.agents||[]" :key="a.agent" :value="a.agent">{{a.agent}} ({{a.n}})</option></select></label><button :disabled="busy">Apply</button></form><div v-if="data?.buckets?.length" class="cc-nofu-buckets"><span>Quick period</span><button v-for="bucket in data.buckets" :key="bucket.days" :aria-pressed="days===bucket.days" @click="days=bucket.days;load()">{{bucket.days}} days <b>{{bucket.n}}</b></button></div><div v-if="data?.statuses?.length" class="cc-nofu-status"><span>Filter outcome</span><label v-for="s in data.statuses" :key="s.status"><input v-model="statuses" type="checkbox" :value="s.status">{{s.status}} <b>{{s.n}}</b></label><button :disabled="busy" @click="load()">Apply outcomes</button></div><p v-if="error" class="cc-error" role="alert">{{error}} <button @click="load()">Retry</button></p><p v-if="data" class="cc-nofu-count">Showing <b>{{rows.length}}</b> of <b>{{data.total}}</b> leads</p><CCDataTable :columns="columns" :rows="rows" :busy="busy"><template #actions="{row}"><button @click="emit('open',row.name)">Open lead</button></template></CCDataTable><div v-if="data&&rows.length<data.total" class="cc-nofu-more"><label>Load<select v-model.number="batchSize"><option :value="15">15 leads</option><option :value="50">50 leads</option><option :value="200">200 leads</option></select></label><button :disabled="busy" @click="load(true)">{{busy?'Loading…':'Load next '+batchSize}}</button></div></section></template>
<style scoped>.cc-nofu-card>header{margin-bottom:16px}.cc-nofu-card h2{margin-bottom:5px}.cc-nofu-card header p{margin:0;color:#64786a;font-size:13px}.cc-nofu-buckets,.cc-nofu-status,.cc-nofu-more{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:12px 0}.cc-nofu-buckets>span,.cc-nofu-status>span{color:#4b6554;font-size:12px;font-weight:800}.cc-nofu-buckets button,.cc-nofu-status button,.cc-nofu-more button{border:1px solid #c7d9cb;border-radius:8px;background:#fff;color:#214d35;padding:7px 10px;cursor:pointer}.cc-nofu-buckets button[aria-pressed=true]{border-color:#1a6841;background:#e2f2e6;color:#134c30}.cc-nofu-buckets b,.cc-nofu-status b{margin-left:4px}.cc-nofu-status{padding:10px 0;border-top:1px solid #e2ece4;border-bottom:1px solid #e2ece4}.cc-nofu-status label{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#425d4b}.cc-nofu-count{margin:14px 0 10px;color:#5d7363;font-size:13px}.cc-check{align-self:center;display:flex!important;align-items:center;gap:7px;color:#425d4b!important;font-size:12px!important;letter-spacing:0!important;text-transform:none!important}.cc-nofu-more{justify-content:flex-end;margin-top:14px}.cc-nofu-more label{display:flex;align-items:center;gap:7px;color:#526b5a;font-size:12px;font-weight:700}.cc-nofu-more select{padding:7px;border:1px solid #c7d9cb;border-radius:7px;background:#fff}@media(max-width:650px){.cc-nofu-buckets,.cc-nofu-status{align-items:flex-start}.cc-nofu-status label{flex:1 1 140px}.cc-nofu-more{justify-content:space-between}}</style>
